def hours_to_xid_wraparound(writes_per_sec: int, current_age: int = 0) -> float:
    if writes_per_sec <= 0:
        raise ValueError('writes_per_sec must be positive')
    remaining = max(0, 2_000_000_000 - current_age)
    return round(remaining / (writes_per_sec * 3600.0), 2)

