def validate_guc_timeouts(idle_tx_sec: int, stmt_sec: int) -> None:
    if idle_tx_sec <= 0 or idle_tx_sec > 60:
        raise ValueError('idle_in_transaction_session_timeout should be between 1s and 60s for OLTP')
    if stmt_sec <= 0:
        raise ValueError('statement_timeout must be positive')

def hot_headroom_bytes(page_size: int = 8192, fillfactor: int = 70) -> int:
    if not (10 <= fillfactor <= 100):
        raise ValueError('fillfactor must be in [10, 100]')
    return int(page_size * (100 - fillfactor) / 100)

def partition_freeze_minutes(partition_gb: float, vacuum_mb_s: float = 80.0) -> float:
    if partition_gb <= 0 or vacuum_mb_s <= 0:
        raise ValueError('Partition size and vacuum speed must be positive')
    return round((partition_gb * 1024.0) / (vacuum_mb_s * 60.0), 2)

def runbook_action(max_datfrozenxid_age: int) -> str:
    if max_datfrozenxid_age >= 1_997_000_000:
        return 'STOP_POOLS -> START_POSTGRES_SINGLE -> VACUUM_FREEZE'
    if max_datfrozenxid_age >= 500_000_000:
        return 'TERMINATE_XMIN_BLOCKERS -> RUN_MANUAL_VACUUM_FREEZE'
    return 'MONITOR_NORMAL_AUTOVACUUM'
